  if (-not (Test-Path -LiteralPath $a[0])) { Write-Host "MANQUANT : $($a[0])" -ForegroundColor Red; $ko++; continue }
  $h = (Get-FileHash -LiteralPath $a[0] -Algorithm SHA256).Hash
  if ($h -ne $a[1]) { Write-Host "DIFFÉRENT : $($a[0])" -ForegroundColor Red; $ko++ } else { $ok++ }
}
