$absents = @($tous | Where-Object { -not (Test-Path -LiteralPath $_) })
if ($absents.Count -gt 0) { Write-Host "$($absents.Count) fichier(s) du dépôt ABSENT(S) (copie qui a remplacé un dossier au lieu de le fusionner ?) :" -ForegroundColor Red; $absents | ForEach-Object { Write-Host "  $_" }; $ko += $absents.Count }
Write-Host "101 : $ok fichier(s) conforme(s), $ko problème(s)."
if ($ko -eq 0) { Write-Host 'Tout est en place.' -ForegroundColor Green }
